#!/usr/bin/env bash
# GENERATED by tools/landed_parent/lp.py: lockstep bench dsdv_seq_host_wf (flat) vs dsdv_seq_host_wf_lp + mutants [1, 2, 4] + region audit.
# Run on the FLEET (ot-run), never on localhost.  Exit 0 iff MUT 0 PASSES, every mutant FAILS and the audit PASSES.
#   bash rtl/dsrom_sys/s81_dv/unit/landed/dsdv_seq_host_wf_lp_bench.sh OUTDIR        (SIM=iverilog default | verilator)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="rtl/dsrom_sys/s81_dv/unit/landed/dsdv_seq_host_wf.sv rtl/lib/ot_async_fifo.sv rtl/lib/ot_reset_sync.sv rtl/lib/ot_rst_relay.sv rtl/link/ot_link_afifo.sv rtl/dsrom_sys/s81_ctrl/ot_s81_secded.sv rtl/hdc/ingest/ot_hdc_ingest_fp8q.sv rtl/hdc/ingest/ot_hdc_kv_ingest.sv rtl/hdc/ingest/ot_rom_host_ingest.sv physical/rom_host_ingest/rtl/dsfd_host.sv rtl/dsrom_sys/s81_ingest/ot_s81_ingest_visibility_fence.sv rtl/dsrom_sys/s81_ingest/dsfd_host_native.sv rtl/dsrom_sys/s81_ingest/dsfd_host_sd.sv rtl/dsrom_sys/s81_ingest/dsfd_host_c.sv rtl/dsrom_sys/s81_static_control/ot_s81_fixed_issue.sv rtl/dsrom_sys/s81_dv/unit/ot_dsdv_fixed_issue.sv rtl/dsrom_sys/s81_dv/unit/ot_dsdv_vstop.sv rtl/dsrom_sys/s81_dv/unit/dsdv_sh_sd.sv rtl/dsrom_sys/s81_dv/unit/dsdv_seq_host.sv physical/asap7_memory_macros_v2/ot_sram_1r1w_128x256_m1_r2c2/ot_sram_1r1w_128x256_m1_r2c2.v rtl/common/landed_parent/ot_pl_land.sv rtl/dsrom_sys/s81_dv/unit/landed/dsdv_seq_host_wf_lp.sv rtl/dsrom_sys/s81_dv/unit/landed/tb_dsdv_seq_host_wf_lp.sv"
python3 tools/landed_parent/lp.py audit rtl/dsrom_sys/s81_dv/unit/landed/dsdv_seq_host_lp_spec.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit rtl/dsrom_sys/s81_dv/unit/landed/dsdv_seq_host_lp_spec.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
for m in 0 1 2 4; do
  if [ "$SIM" = verilator ]; then
    verilator --binary -j 8 -Wno-fatal --top-module tb_dsdv_seq_host_wf_lp -GMUT=$m -DDSFD_HOST_C_STATIC $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
      && "$OUT/obj$m/Vtb_dsdv_seq_host_wf_lp" > "$OUT/mut$m.log" 2>&1
  else
    iverilog -g2012 -o "$OUT/sim$m" -s tb_dsdv_seq_host_wf_lp -Ptb_dsdv_seq_host_wf_lp.MUT=$m -DDSFD_HOST_C_STATIC $SRCS > "$OUT/build_$m.log" 2>&1 \
      && vvp -n "$OUT/sim$m" > "$OUT/mut$m.log" 2>&1
  fi
  r=$(grep -o 'LP_LOCKSTEP [A-Z]*' "$OUT/mut$m.log" 2>/dev/null | head -1)
  echo "MUT $m: ${r:-NO_RESULT (see $OUT/build_$m.log)}"
  if [ $m -eq 0 ]; then [ "$r" = "LP_LOCKSTEP PASS" ] || rc=1; else [ "$r" = "LP_LOCKSTEP FAIL" ] || rc=1; fi
done
echo "BENCH_EXIT $rc"; exit $rc
